def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    reqs = [WATER_REQ]
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            reqs.append(opp.get('water_requirement', WATER_REQ))
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    b = float(prev.get('bid', 0))
                    if b >= 0:
                        prev_bids.append(b)
                except Exception:
                    pass

    total_req = sum(reqs)
    scarcity = total_req / max(supply, 1.0)
    tight_supply = supply <= 17.0
    abundant_supply = supply >= 22.0

    if not alive:
        if hp <= 3 or no_water_days >= 2:
            return max(0.0, min(budget, DAILY_SALARY * 0.75))
        return max(0.0, min(budget, DAILY_SALARY * 0.2))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    emergency = hp <= 3 or no_water_days >= 2
    caution = hp <= 5 or no_water_days >= 1

    if emergency:
        bid = max(DAILY_SALARY * 1.05, highest_prev + 3.0)
    elif tight_supply or scarcity > 2.6:
        bid = max(DAILY_SALARY * 0.95, highest_prev + 2.0)
    elif caution:
        bid = max(DAILY_SALARY * 0.72, avg_prev + 1.5)
    elif abundant_supply and highest_prev >= DAILY_SALARY * 1.6:
        bid = DAILY_SALARY * 0.28
    elif abundant_supply:
        bid = DAILY_SALARY * 0.42
    else:
        bid = max(DAILY_SALARY * 0.52, min(highest_prev + 1.0, DAILY_SALARY * 0.88))

    if day >= 8 and hp >= 6 and no_water_days == 0 and budget < DAILY_SALARY * 2.2:
        bid = min(bid, DAILY_SALARY * 0.45)

    if budget <= DAILY_SALARY * 0.6:
        if emergency:
            bid = budget
        else:
            bid = min(bid, budget * 0.75)

    bid = max(0.0, min(budget, bid))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids from immediate previous_trace only
    yesterday_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev = max(yesterday_bids) if yesterday_bids else 0.0

    # If high-pressure bidders exist yesterday, we need to compete but not overpay.
    # Use a capped target bid based on supply: higher supply -> less need to overbid.
    # supply in [15,25] => scale from 1.0 to ~0.7
    supply_scale = 1.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_scale = 1.0 - (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) * 0.3
        if supply_scale < 0.7:
            supply_scale = 0.7
        if supply_scale > 1.0:
            supply_scale = 1.0

    # Determine urgency from our hp and consecutive no-water days.
    urgency = 0.0
    if my_hp <= 2.0:
        urgency += 1.0
    elif my_hp <= 4.0:
        urgency += 0.6
    if my_no_water_days >= 2:
        urgency += 0.6
    elif my_no_water_days == 1:
        urgency += 0.3

    # Base bid levels
    # - If yesterday had very high bids, we bid near a fraction of that but add a small buffer.
    # - If yesterday bids were low, bid moderately.
    if highest_prev >= DAILY_SALARY * 0.85:
        target = (highest_prev * 0.55 + 5.0) * supply_scale
    elif highest_prev >= DAILY_SALARY * 0.45:
        target = (highest_prev * 0.35 + 25.0) * supply_scale
    else:
        target = (DAILY_SALARY * 0.5) * supply_scale

    # Increase target under urgency
    target *= (1.0 + 0.35 * urgency)

    # Budget safety: never bid more than we can afford; also avoid bidding above a reasonable fraction of budget.
    max_reasonable = my_budget
    # Keep some budget for later days
    keep_fraction = 0.65
    if day is not None and int(day) >= 7:
        keep_fraction = 0.45
    max_reasonable = min(max_reasonable, my_budget * (1.0 - keep_fraction) + 1e-9)

    # Ensure at least a minimum bid to have a chance
    min_bid = DAILY_SALARY * 0.25
    bid = max(min_bid, target)

    # If we are critically low on hp, be aggressive up to most of budget
    if my_hp <= 2.0:
        bid = max(bid, DAILY_SALARY * 0.85)
        bid = min(bid, my_budget)
    else:
        bid = min(bid, my_budget)

    # Final clamp to non-negative
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    hp = my_status['hp']
    budget = my_status['budget']
    alive = [o for o in opponents_status.values() if o['alive']]

    # Collect yesterday bids from alive opponents
    prev_bids = []
    for opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev['bid'])

    # If no previous bids (first day or all new), use conservative baseline
    if not prev_bids:
        if hp <= 2:
            return min(budget, DAILY_SALARY * 0.8)
        elif hp <= 4:
            return min(budget, DAILY_SALARY * 0.5)
        else:
            return min(budget, max(0, DAILY_SALARY * 0.2))

    # Determine highest previous bid
    highest_prev = max(prev_bids)

    # If we need water desperately, bid slightly above highest previous
    if hp <= 2:
        target = highest_prev + 1.5
        return min(budget, target)
    elif hp <= 4:
        # Moderate need: bid if highest prev is not too high
        if highest_prev > DAILY_SALARY * 0.8:
            return min(budget, DAILY_SALARY * 0.4)
        else:
            target = max(highest_prev + 1.0, DAILY_SALARY * 0.4)
            return min(budget, target)
    else:
        # High HP: conserve budget
        return min(budget, max(0, DAILY_SALARY * 0.1))
